import json
import sys
import time
import urllib.request
import urllib.error

BASE = "http://localhost:8080"
LOG = open("/tmp/recon/log.txt", "w")


def log(msg):
    LOG.write(msg + "\n")
    LOG.flush()


def request(method, path, token=None):
    """Return (status, headers, body_text). Retries transport errors and 5xx."""
    attempts = 0
    while True:
        attempts += 1
        headers = {}
        if token:
            headers["Authorization"] = "Bearer " + token
        req = urllib.request.Request(BASE + path, method=method, headers=headers)
        try:
            with urllib.request.urlopen(req, timeout=30) as resp:
                return resp.status, resp.headers, resp.read().decode()
        except urllib.error.HTTPError as e:
            body = e.read().decode(errors="replace")
            log(f"{method} {path} -> {e.code} {body[:200]} retry-after={e.headers.get('Retry-After')}")
            if e.code == 429:
                wait = e.headers.get("Retry-After")
                wait = float(wait) if wait else 5.0
                time.sleep(wait)
                continue
            if e.code >= 500 and attempts < 20:
                time.sleep(2)
                continue
            return e.code, e.headers, body
        except (urllib.error.URLError, TimeoutError, ConnectionError) as e:
            log(f"{method} {path} transport error {e!r}")
            if attempts < 20:
                time.sleep(2)
                continue
            raise


class Client:
    def __init__(self):
        self.token = None
        self.token_fetches = 0

    def fetch_token(self):
        status, _, body = request("POST", "/token")
        self.token = json.loads(body)["token"]
        self.token_fetches += 1

    def get_json(self, path):
        """GET an authenticated path; refresh token on 401 and retry."""
        if self.token is None:
            self.fetch_token()
        for _ in range(10):
            status, _, body = request("GET", path, self.token)
            if status == 401:
                log(f"401 on {path}, refreshing token")
                self.fetch_token()
                continue
            if status == 200:
                return json.loads(body)
            if status == 404:
                return None
            log(f"unexpected status {status} for {path}: {body[:200]}")
            time.sleep(2)
        raise RuntimeError(f"could not fetch {path}")


def main():
    c = Client()
    pages = []
    page = 1
    total_pages = None
    while True:
        data = c.get_json(f"/orders?page={page}")
        pages.append({"page": page, "items": data["items"], "next": data.get("next"),
                      "total_pages": data.get("total_pages")})
        log(f"page {page} items={len(data['items'])} total_pages={data.get('total_pages')} next={data.get('next')}")
        total_pages = data.get("total_pages")
        if data.get("next") is None or page >= total_pages:
            break
        page += 1

    customers = {}
    for p in pages:
        for o in p["items"]:
            cid = o["customer_id"]
            if cid not in customers:
                customers[cid] = c.get_json(f"/customers/{cid}")
    with open("/tmp/recon/raw.json", "w") as f:
        json.dump({"pages": pages, "customers": customers,
                   "token_fetches": c.token_fetches}, f)
    log(f"done: pages={len(pages)} customers={len(customers)} token_fetches={c.token_fetches}")


if __name__ == "__main__":
    main()

